#!/usr/bin/env python3
"""renders docs/results.md from docs/raw/*.json. numbers only come from
files the scripts wrote, nothing is typed in by hand"""
import json
import os
import sys

raw = sys.argv[1]


def load(name):
    p = os.path.join(raw, name)
    if not os.path.exists(p):
        return None
    with open(p) as f:
        return json.load(f)


def env_line(e):
    if not e:
        return ""
    return f"kernel {e['kernel']}, {e['arch']}, {e['cpus']} CPUs, {e['mem_gib']} GiB, {e['date']}"


def pct(x):
    return f"{x * 100:.2f}%"


out = ["# iolens results", "",
       "Generated by `scripts/results.sh` from the raw output in `docs/raw/`. "
       "Misses are listed the same as passes.", ""]
summary = []

v1 = load("v1.json")
out.append("## V1: latency accuracy (null_blk)")
out.append("")
if v1:
    out.append(f"Environment: {env_line(v1['env'])}")
    out.append("")
    out.append("| configured | requests | iolens p50 | iolens p99 | fio p50 | fio p99 | worst error | pass |")
    out.append("| --- | --- | --- | --- | --- | --- | --- | --- |")
    allok = True
    for r in v1["runs"]:
        worst = max(v for k, v in r.items() if k.startswith("err_"))
        allok &= r["pass"]
        out.append(f"| {r['configured_ms']:.0f} ms | {r['requests']} | {r['iolens_p50_us']/1000:.2f} ms | "
                   f"{r['iolens_p99_us']/1000:.2f} ms | {r['fio_p50_us']/1000:.2f} ms | {r['fio_p99_us']/1000:.2f} ms | "
                   f"{pct(worst)} | {'yes' if r['pass'] else 'no'} |")
    summary.append(("Latency accuracy", "within 25%", "pass" if allok else "miss"))
else:
    out.append("Not run yet. Needs `null_blk`, which the kernel used so far (Docker Desktop's linuxkit 6.10) "
               "does not ship. Run `sudo ./scripts/v1_latency.sh` in the Lima VM.")
    summary.append(("Latency accuracy", "within 25%", "not run"))
out.append("")

v2 = load("v2.json")
out.append("## V2: device statistics vs iostat")
out.append("")
if v2:
    r = v2["result"]
    out.append(f"Environment: {env_line(v2['env'])}. Device `{r['device']}`, {r['windows']} aligned 1 s windows, "
               "fio 70/30 random read/write, 4K and 64K blocks, queue depth 16.")
    out.append("")
    out.append("| column | median error | p90 error | target | pass |")
    out.append("| --- | --- | --- | --- | --- |")
    for k, c in r["columns"].items():
        out.append(f"| {k} | {pct(c['median_err'])} | {pct(c['p90_err'])} | {pct(c['tolerance'])} | {'yes' if c['pass'] else 'no'} |")
    out.append("")
    out.append("The pass check is on the median per-window error. The p90 is higher because the two tools "
               "still sample a few milliseconds apart, and a bursty load moves a lot of requests across a "
               "window edge in that time.")
    summary.append(("Device-stat parity", "2% rates, 5% await", "pass (median)" if r["pass"] else "miss"))
else:
    out.append("Not run yet.")
    summary.append(("Device-stat parity", "2% rates, 5% await", "not run"))
out.append("")

v3 = load("v3.json")
out.append("## V3: attribution")
out.append("")
if v3:
    out.append(f"Environment: {env_line(v3['env'])}. Two fio writers in two cgroups at the same time, 512 MiB and 256 MiB.")
    out.append("")
    out.append("| mode | cgroup | fio wrote | iolens | io.stat | error vs fio | error vs io.stat |")
    out.append("| --- | --- | --- | --- | --- | --- | --- |")
    allok = True
    for run in v3["runs"]:
        allok &= run["pass"]
        for c, v in run["cgroups"].items():
            out.append(f"| {run['mode']} | {c} | {v['fio_bytes']/2**20:.1f} MiB | {v['iolens_bytes']/2**20:.1f} MiB | "
                       f"{v['io_stat_wbytes']/2**20:.1f} MiB | {pct(v['err_vs_fio'])} | {pct(v['err_vs_io_stat'])} |")
    out.append("")
    out.append("Buffered writes are flushed by kernel writeback threads, not by fio. They still land on the "
               "writer's cgroup because iolens reads `bio->bi_blkg`, not the current task. Journal and metadata "
               "writes go to the root cgroup: " + ", ".join(
                   f"{r['unattributed_or_root_bytes']/2**20:.1f} MiB ({r['mode']})" for r in v3["runs"]) + ".")
    summary.append(("Attribution", "within 1%", "pass" if allok else "miss"))
else:
    out.append("Not run yet.")
    summary.append(("Attribution", "within 1%", "not run"))
out.append("")

v4 = load("v4.json")
out.append("## V4: overhead")
out.append("")
if v4:
    out.append(f"Environment: {env_line(v4['env'])}. Device: `{v4['device']}`.")
    if v4["device"] != "null_blk":
        out.append("")
        out.append("**Not the reference setup.** null_blk was not available, so this used a loop device on tmpfs. "
                   "It is still a near zero latency device (about 1M IOPS here), so it is close to the worst case, "
                   "but the number should be redone on null_blk in the Lima VM.")
    out.append("")
    out.append("| | mean IOPS | std dev |")
    out.append("| --- | --- | --- |")
    out.append(f"| iolens off | {v4['iops_off_mean']:.0f} | {v4['iops_off_sd']:.0f} |")
    out.append(f"| iolens on | {v4['iops_on_mean']:.0f} | {v4['iops_on_sd']:.0f} |")
    out.append("")
    out.append(f"IOPS loss: **{v4['loss_pct']:.1f}%** (target at most 5%, {'met' if v4['pass'] else 'missed'}).")
    out.append("")
    ns = v4["ns_per_event"]
    out.append("Per event cost from kernel BPF stats: " + ", ".join(f"{k} {v:.0f} ns" for k, v in sorted(ns.items())) +
               ". Insert only fires when a request goes through the scheduler, so it is rare on this device and "
               "its average is noisy. Enabling BPF stats itself adds a little per event.")
    per_req = ns.get("issue", 0) + ns.get("complete", 0)
    out.append("")
    out.append(f"What that means on a real disk: issue plus complete is about {per_req:.0f} ns per request. "
               f"A disk request of 100 us (fast NVMe) would pay {per_req / 100_000 * 100:.2f}% extra, "
               f"a 1 ms request {per_req / 1_000_000 * 100:.3f}%.")
    out.append("")
    out.append(f"Agent while running: {v4['agent_cpu_cores']*100:.2f}% of one core, {v4['agent_rss_mib']:.0f} MiB RSS.")
    out.append("")
    out.append("Most likely cause of the miss: all 4 fio jobs complete I/O for the same (cgroup, device, op) key, so "
               "the atomic adds on that one `hists` entry bounce a cache line between CPUs. That is the known cost "
               "from the spec; the per-CPU variant is the next step.")
    summary.append(("Overhead", "at most 5% IOPS loss", f"{v4['loss_pct']:.1f}% ({'met' if v4['pass'] else 'missed'}, {v4['device']})"))
    summary.append(("Per-event cost", "reported", f"issue {ns.get('issue', 0):.0f} ns, complete {ns.get('complete', 0):.0f} ns"))
    fp = v4["agent_rss_mib"] < 100 and v4["agent_cpu_cores"] < 0.02
    summary.append(("Agent footprint", "under 100 MB RSS, under 2% of a core",
                    f"{v4['agent_rss_mib']:.0f} MiB, {v4['agent_cpu_cores']*100:.2f}% (under load, not idle)"
                    + ("" if fp else ", missed")))
else:
    out.append("Not run yet.")
    summary.append(("Overhead", "at most 5% IOPS loss", "not run"))
out.append("")

runs = []
p = os.path.join(raw, "demo-runs.jsonl")
if os.path.exists(p):
    runs = [json.loads(l) for l in open(p) if l.strip()]
out.append("## V5: detection (make demo)")
out.append("")
if runs:
    out.append("| run | device | fired after | culprit | victim | victim p99 | cleared after | pass |")
    out.append("| --- | --- | --- | --- | --- | --- | --- | --- |")
    for r in runs:
        f = r["finding"] or {}
        ev = f.get("evidence", {})
        p99 = (f"{ev['victim_p99_baseline_us']/1000:.1f} -> {ev['victim_p99_us']/1000:.1f} ms ({ev['factor']:.0f}x)"
               if ev else "-")
        out.append(f"| {r['run']} | {f.get('device', r['device'])} | {r['fired_after_s']} s | {f.get('culprit', '-')} | "
                   f"{f.get('victim', '-')} | {p99} | {r['cleared_after_s']} s | {'yes' if r['pass'] else 'no'} |")
    npass = sum(r["pass"] for r in runs)
    out.append("")
    out.append(f"{npass} of {len(runs)} runs passed (fired within 10 s naming the right pods, cleared within 30 s).")
    summary.append(("Detection", "5 of 5 within 10 s", f"{npass} of {len(runs)}"))
else:
    out.append("Not run yet.")
    summary.append(("Detection", "5 of 5 within 10 s", "not run"))
out.append("")

head = ["## Summary", "", "| criterion | target | result |", "| --- | --- | --- |"]
head += [f"| {a} | {b} | {c} |" for a, b, c in summary]
print("\n".join(out[:4] + head + [""] + out[4:]))
